sys_script_client.script:
function onSubmit() {

    var total = parseFloat(g_form.getValue('total_cost')) || 0;
    var justification = (g_form.getValue('justification') || '').trim();

    if (total > 500 && justification.length < 20) {
        g_form.addErrorMessage('Please explain the business need (at least 20 characters) for requests over 500.');
        g_form.showFieldMsg('justification', 'Required for requests over 500.', 'error');
        return false;   // cancels the submit
    }

    var qty = parseInt(g_form.getValue('quantity'), 10);
    if (isNaN(qty) || qty < 1 || qty > 10) {
        g_form.showFieldMsg('quantity', 'Enter a quantity between 1 and 10.', 'error');
        return false;
    }
    return true;

}
